-- specarch: #/entities/Book
CREATE TABLE books (
    -- specarch: #/entities/Book/properties/id
    id UUID NOT NULL,
    -- specarch: #/entities/Book/properties/authorId
    author_id UUID NOT NULL,
    -- specarch: #/entities/Book/properties/title
    title VARCHAR(300) NOT NULL,
    CONSTRAINT pk_books PRIMARY KEY (id)
);

ALTER TABLE books ADD CONSTRAINT fk_books_author_id FOREIGN KEY (author_id) REFERENCES authors (id) ON DELETE RESTRICT;

CREATE VIEW book_with_author AS
SELECT
    t0.id,
    t0.author_id,
    t0.title,
    t1.name AS author_name
FROM books t0
    LEFT JOIN authors t1 ON t1.id = t0.author_id;
